class Solution:
    def kthSmallestSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        sums = []
        for i in range(n):
            cur = 0
            for j in range(i, n):
                cur += nums[j]
                sums.append(cur)
        sums.sort()
        return sums[k - 1]

