class Solution {
public:
    int kthSmallestSubarraySum(vector<int>& nums, int k) {
        int n = nums.size();
        vector<long long> sums;
        sums.reserve((long long)n * (n + 1) / 2);
        for (int i = 0; i < n; ++i) {
            long long cur = 0;
            for (int j = i; j < n; ++j) {
                cur += nums[j];
                sums.push_back(cur);
            }
        }
        nth_element(sums.begin(), sums.begin() + k - 1, sums.end());
        return (int)sums[k - 1];
    }
};

