class Solution {
public:
    int kthSmallestSubarraySum(vector<int>& nums, int k) {
        auto countAtMost = [&](long long limit) {
            long long total = 0, cur = 0;
            int left = 0;
            for (int right = 0; right < (int)nums.size(); ++right) {
                cur += nums[right];
                while (cur > limit) cur -= nums[left++];
                total += right - left + 1;
            }
            return total;
        };
        long long lo = *min_element(nums.begin(), nums.end());
        long long hi = accumulate(nums.begin(), nums.end(), 0LL);
        while (lo < hi) {
            long long mid = lo + (hi - lo) / 2;
            if (countAtMost(mid) >= k) hi = mid;
            else lo = mid + 1;
        }
        return (int)lo;
    }
};

