class Solution {
    public int kthSmallestSubarraySum(int[] nums, int k) {
        long lo = Long.MAX_VALUE;
        long hi = 0;
        for (int x : nums) {
            lo = Math.min(lo, x);
            hi += x;
        }
        while (lo < hi) {
            long mid = lo + (hi - lo) / 2;
            if (countAtMost(nums, mid) >= k) hi = mid;
            else lo = mid + 1;
        }
        return (int) lo;
    }

    private long countAtMost(int[] nums, long limit) {
        long total = 0, cur = 0;
        int left = 0;
        for (int right = 0; right < nums.length; ++right) {
            cur += nums[right];
            while (cur > limit) cur -= nums[left++];
            total += right - left + 1;
        }
        return total;
    }
}

